	void refusesATransferAgainstAnAccountThatDoesNotExist() {
		long missing = 404L;

		assertThatThrownBy(() -> reservation.reserve(transferOf(10_00L, SOURCE, missing)))
				.asInstanceOf(type(UnknownAccountException.class))
				.satisfies(refused -> assertThat(refused.getAccountId()).isEqualTo(missing));

		assertThat(reservedAmountOf(SOURCE)).isZero();
		assertThat(transferRows()).isEmpty();
	}

	/**
	 * Ticket 14 moved this refusal ahead of the lock, so what reaches the database here is
	 * nothing at all — not even the {@code select … for update} that {@code AccountLocking}'s
	 * own {@link IllegalArgumentException} backstop would have raised.
	 */
	@Test
	@DisplayName("a Transfer from an Account to itself is refused before the tables are touched")
	void refusesATransferFromAnAccountToItself() {
		assertThatThrownBy(() -> reservation.reserve(transferOf(10_00L, SOURCE, SOURCE)))
				.isInstanceOf(SelfTransferNotAllowedException.class);

		assertThat(reservedAmountOf(SOURCE)).isZero();
		assertThat(transferRows()).isEmpty();
	}
